package com.finanscore.payment.infrastructure; import com.finanscore.payment.domain.PaymentProcessorPort;import org.springframework.stereotype.Component; @Component public class SimulatedPaymentAdapter implements PaymentProcessorPort{public PaymentDecision process(CardData c){String n=c.number().replaceAll("\\s","");if(n.matches("0+"))return new PaymentDecision(false,"INVALID_CARD","Pago no válido");if(!n.matches("\\d{13,19}"))return new PaymentDecision(false,"INVALID_FORMAT","Número de tarjeta inválido");if(!c.expiry().matches("(0[1-9]|1[0-2])/\\d{2}"))return new PaymentDecision(false,"INVALID_EXPIRY","Fecha MM/AA inválida");if(!c.cvv().matches("\\d{3,4}"))return new PaymentDecision(false,"INVALID_CVV","CVV inválido");return new PaymentDecision(true,"APPROVED","Pago aprobado");}}